import cadquery as cq
O = [(-100, 41), (-98, -9), (-97, -17), (-94.5, -25), (-90, -32), (-84, -38), (-77, -41), (50, -41), (56, -40.4), (61, -38.7), (66, -35.8), (71, -31.8), (75.4, -26.7), (79.8, -20.6), (83.9, -13.6), (87.6, -5.6), (91.1, 3.2), (94.1, 12.7), (96.7, 22.9), (98.9, 33.6), (100, 41)]
I = [(-91.4, 42), (-91.4, -18), (-88, -26), (-82.8, -30), (-76, -31.3), (49.3, -32.1), (56, -30.2), (60.6, -27.5), (64.9, -23.8), (69.1, -19.1), (73.1, -13.5), (76.9, -6.9), (80.3, 0.5), (83.4, 8.7), (86.2, 17.5), (88.6, 26.9), (91.6, 42)]
side = lambda P, w: cq.Workplane('YZ', origin=(-w, 0, 0)).polyline(P).close().extrude(2 * w)   # 옆 단면을 x 로 밀기
B = lambda sx, sy, sz, x, y, z: cq.Workplane('XY').box(sx, sy, sz).translate((x, y, z))
r = side(O, 51.8)
r = r.faces('>X').edges('not(>Z)').fillet(11).faces('<X').edges('not(>Z)').fillet(11)   # 바깥 옆 모서리 둥글게
r = r.cut(side(I, 45).intersect(B(100, 300, 70, 0, 0, 12))).cut(side(I, 37))   # 속 비움 · 아래 턱
r = r.cut(B(70, 115, 40, 0, -12.5, -40))                                          # 바닥 큰 구멍
for x in (-20, 0, 20): r = r.cut(B(7, 20, 48, x, -95, 2))                          # 앞 세로 홈
